// hero figure: training and validation loss curves
function lossFig(){
  let s = 7; const rnd = () => (s = (s * 16807) % 2147483647) / 2147483647;
  const W = 260, H = 112, x0 = 26, y0 = 10, x1 = 252, y1 = 92, n = 60;
  const pt = (i, f) => [x0 + (x1 - x0) * i / (n - 1), y0 + (y1 - y0) * (1 - f)];
  const tr = [], va = [];
  for (let i = 0; i < n; i++) { const t = i / (n - 1), base = 0.08 + 0.86 * Math.exp(-4.2 * t);
    tr.push(pt(i, base + (rnd() - 0.5) * 0.07 * (1 - t * 0.6)));
    if (i % 6 === 0 || i === n - 1) va.push(pt(i, 0.13 + 0.8 * Math.exp(-3.6 * t) + 0.05 * t * t)); }
  const d = a => a.map((p, i) => (i ? 'L' : 'M') + p[0].toFixed(1) + ' ' + p[1].toFixed(1)).join('');
  return `<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="Training and validation loss falling over steps">
    <g stroke="var(--line)" stroke-width="1">${[0.25,0.5,0.75].map(f => `<line x1="${x0}" x2="${x1}" y1="${y0 + (y1 - y0) * f}" y2="${y0 + (y1 - y0) * f}"/>`).join('')}</g>
    <path d="M${x0} ${y0}V${y1}H${x1}" fill="none" stroke="var(--line2)" stroke-width="1.2"/>
    <path d="${d(tr)}" fill="none" stroke="var(--accent)" stroke-width="2" stroke-linejoin="round"/>
    <path d="${d(va)}" fill="none" stroke="var(--ink)" stroke-width="1.6" stroke-dasharray="4 3"/>
    ${va.map(p => `<circle cx="${p[0].toFixed(1)}" cy="${p[1].toFixed(1)}" r="2.4" fill="var(--card)" stroke="var(--ink)" stroke-width="1.3"/>`).join('')}
    <text x="${x0 - 6}" y="${y0 + 8}" text-anchor="end" font-size="9" fill="var(--muted)" font-family="var(--mono)">L</text>
    <text x="${x1}" y="${H - 4}" text-anchor="end" font-size="9" fill="var(--muted)" font-family="var(--mono)">steps</text>
    <text x="${x1 - 2}" y="${y0 + 12}" text-anchor="end" font-size="9" fill="var(--accent)" font-family="var(--mono)">train</text>
    <text x="${x1 - 2}" y="${y0 + 24}" text-anchor="end" font-size="9" fill="var(--ink)" font-family="var(--mono)">val</text>
  </svg>`;
}

