  const [x0, x1] = o.x || [-5, 5], [y0, y1] = o.y || [-5, 5];
  const wrap = document.createElement('div'); wrap.className = 'vplot'; host.appendChild(wrap);
  const svg = S('svg', {viewBox: `0 0 ${W} ${H}`, role: 'img', 'aria-label': o.label || 'Interactive chart'}, wrap);
  const X = v => P[3] + (v - x0) / (x1 - x0) * (W - P[1] - P[3]);
  const Y = v => H - P[2] - (v - y0) / (y1 - y0) * (H - P[0] - P[2]);
  const IX = px => x0 + (px - P[3]) / (W - P[1] - P[3]) * (x1 - x0);
  const IY = py => y0 + (H - P[2] - py) / (H - P[0] - P[2]) * (y1 - y0);
  const cid = 'vzc' + Math.random().toString(36).slice(2, 8), defs = S('defs', {}, svg), cp = S('clipPath', {id: cid}, defs);
  S('rect', {x: P[3], y: P[0], width: W - P[1] - P[3], height: H - P[0] - P[2]}, cp);
  const grid = S('g', {class: 'vgrid'}, svg), layer = S('g', {'clip-path': `url(#${cid})`}, svg), top = S('g', {}, svg);
  if (o.axes !== false) {
    (o.xt === 0 ? [] : niceTicks(x0, x1, o.xt || 6)).forEach(t => { S('line', {x1: X(t), x2: X(t), y1: Y(y0), y2: Y(y1), class: t === 0 ? 'ax' : 'gl'}, grid); const tx = S('text', {x: X(t), y: H - P[2] + 16, 'text-anchor': 'middle', class: 'tk'}, grid); tx.textContent = +t.toFixed(4); });
    (o.yt === 0 ? [] : niceTicks(y0, y1, o.yt || 5)).forEach(t => { S('line', {x1: X(x0), x2: X(x1), y1: Y(t), y2: Y(t), class: t === 0 ? 'ax' : 'gl'}, grid); const tx = S('text', {x: P[3] - 6, y: Y(t) + 4, 'text-anchor': 'end', class: 'tk'}, grid); tx.textContent = +t.toFixed(4); });
    if (o.xl) { const t = S('text', {x: W - P[1], y: H - 4, 'text-anchor': 'end', class: 'tk al'}, grid); t.textContent = o.xl; }
    if (o.yl) { const t = S('text', {x: P[3] + 4, y: P[0] + 10, class: 'tk al'}, grid); t.textContent = o.yl; }
  }
  const path = (pts, cls, extra = {}) => { const d = pts.filter(p => isFinite(p[1])).map((p, i) => (i ? 'L' : 'M') + X(p[0]).toFixed(1) + ' ' + Y(clamp(p[1], y0 - (y1 - y0), y1 + (y1 - y0))).toFixed(1)).join(''); return S('path', {d, class: cls, ...extra}, layer); };
  const fn = (f, cls, n = 240, a = x0, b = x1) => path(lin(a, b, n).map(x => [x, f(x)]), cls);
  const clear = () => { layer.innerHTML = ''; top.innerHTML = ''; };
