    pl.clear(); contours();
    for (let i = 1; i < path.length; i++) pl.line(path[i - 1][0], path[i - 1][1], path[i][0], path[i][1], 'trail');
    path.forEach((q, i) => pl.dot(q[0], q[1], i === path.length - 1 ? 'pt big' : 'pt sm', i === path.length - 1 ? 6 : 3));
    const q = path[path.length - 1], gr = g(...q), n = Math.hypot(...gr) || 1;
    pl.arrow(q[0], q[1], q[0] - gr[0] / n * 1.2, q[1] - gr[1] / n * 1.2, 'arr c3');
    const s = pl.dot(start[0], start[1], 'pt ring', 9, pl.top); draggable(pl, s, (x, y) => { start = [clamp(x, -4.8, 4.8), clamp(y, -3.8, 3.8)]; reset(); });
    const diverge = Math.abs(1 - 2 * lr * B) > 1;
    ro.innerHTML = kv([['step', path.length - 1], ['w', `(${fmt(q[0])}, ${fmt(q[1])})`], ['loss f(w)', fmt(f(...q), 3), 'hi'], ['gradient', `(${fmt(gr[0])}, ${fmt(gr[1])})`]])
