    ro.innerHTML = kv([['β', fmt(beta, 2)], ['roughly averages the last', fmt(1 / (1 - beta), 0) + ' steps', 'hi']]) + `<span class="hint">${corr ? 'Bias correction divides by 1 − βᵗ, which removes the slow start from 0.' : 'Starting from 0 makes the early average too low. Turn on bias correction to fix it.'} Higher β is smoother but reacts later to the jump at t = 70.</span>`;
