    box.innerHTML = `<div class="bcol"><span>A (${m}, ${n})</span>${g(m, n, 'a', Av, i => i === si)}</div><span class="op">@</span><div class="bcol"><span>B (${n}, ${q})</span>${g(n, q, 'b', Bv, (k, j) => j === sj)}</div><span class="op">=</span><div class="bcol"><span>C (${m}, ${q})</span>${g(m, q, 'r pick', Cv, (i, j) => i === si && j === sj)}</div>`;
    box.querySelectorAll('.g.r i').forEach(el => el.onclick = () => { si = +el.dataset.i; sj = +el.dataset.j; draw(); });
    const terms = Array.from({length: n}, (_, k) => `${Av(si, k)}·${Bv(k, sj)}`.replace(/-/g, '−'));
    ro.innerHTML = kv([[`C[${si}, ${sj}] = row ${si} of A · column ${sj} of B`, terms.join(' + ') + ' = ' + Cv(si, sj), 'hi'], ['shape rule', `(${m}, ${n}) @ (${n}, ${q}) → (${m}, ${q})`], ['multiply-adds', `${m}·${n}·${q} = ${m * n * q}`]]) + '<span class="hint">Tap any cell of C. Each entry is one dot product: a row of A with a column of B. The inner sizes must match, and they disappear from the result.</span>';
