  const pl = Plot(host, {x: [-3.5, 3.5], y: [0, 1], h: 200, yt: 1});
  const ro = readout(host);
  function build(){ ctl.innerHTML = '';
    if (mode === 'arange') { slider(ctl, 'start', -3, 2, 0.25, a, v => { a = v; draw(); }); slider(ctl, 'end', -2, 3, 0.25, b, v => { b = v; draw(); }); slider(ctl, 'step', 0.1, 1, 0.05, st, v => { st = v; draw(); }); }
    else if (mode === 'linspace') { slider(ctl, 'start', -3, 2, 0.25, a, v => { a = v; draw(); }); slider(ctl, 'end', -2, 3, 0.25, b, v => { b = v; draw(); }); slider(ctl, 'steps', 2, 20, 1, n, v => { n = v; draw(); }); }
    else slider(ctl, 'how many samples', 10, 5000, 10, N, v => { N = v; draw(); }); }
