    if (mode === 'arange') { for (let x = a; x < b - 1e-9 && xs.length < 200; x += st) xs.push(+x.toFixed(6)); call = `torch.arange(${a}, ${b}, ${st})`; }
    if (mode === 'linspace') { xs = lin(a, b, n).map(v => +v.toFixed(4)); call = `torch.linspace(${a}, ${b}, ${n})`; }
