      const bins = 28, w = 7 / bins, cnt = Array(bins).fill(0); smp.forEach(v => { const k = Math.floor((v + 3.5) / w); if (k >= 0 && k < bins) cnt[k]++; });
      const mx = Math.max(...cnt) || 1; cnt.forEach((v, k) => S('rect', {x: pl.X(-3.5 + k * w) + 1, y: pl.Y(0.9 * v / mx), width: pl.X(w) - pl.X(0) - 2, height: pl.Y(0) - pl.Y(0.9 * v / mx), class: 'vbar', rx: 2}, pl.layer));
