    let ok = 0; data.forEach(([x, y]) => { const pr = w[0] * x[0] + w[1] * x[1] + b > 0 ? 1 : 0; ok += pr === y; pl.dot(x[0], x[1], y ? 'pt c1f' : 'pt c2f', 4.5); });
    const h = pl.dot(probe[0], probe[1], 'pt ring', 7, pl.top); draggable(pl, h, (x, y) => { probe = [clamp(x, -3, 3), clamp(y, -3, 3)]; draw(); });
