  const T = {sine: x => Math.sin(x), bump: x => Math.exp(-x * x) * 1.6 - 0.3, step: x => x > 0 ? 1 : -0.5, abs: x => Math.abs(x) * 0.6 - 0.6};
  const X = lin(-3, 3, 40).map(x => [x]);
  const pl = Plot(host, {x: [-3, 3], y: [-2, 2], h: 280, xl: 'input x', yl: 'output'});
  const c = controls(host);
  slider(c, 'neurons in the hidden layer', 1, 16, 1, H, v => { H = v; reset(); });
  choose(c, Object.keys(T), tgt, v => { tgt = v; reset(); });
  const bt = buttons(c, [['train', b => { run = !run; b.textContent = run ? 'pause' : 'train'; b.classList.toggle('on', run); if (run) loop(); }], ['reset', () => reset()]]);
  const ro = readout(host);
