    pl.fn(T[tgt], 'guide', 200);
    X.forEach(x => pl.dot(x[0], T[tgt](x[0]), 'pt sm muted', 2.5));
    pl.fn(x => mlpFwd(net, [x]).out[0], 'c1 thick', 200);
    let mse = 0; X.forEach(x => { mse += (mlpFwd(net, x).out[0] - T[tgt](x[0])) ** 2; });
    ro.innerHTML = kv([['training steps', steps], ['mean squared error', fmt(mse / X.length, 4), 'hi'], ['parameters', 3 * H + 1]]) +
      '<span class="hint">Press train. Each faint blue line is one hidden neuron\'s contribution: a ReLU hinge, scaled by its output weight. The teal curve is their sum plus a bias. More neurons give more hinges and a closer fit.</span>';
